import Foundation
import SwanCore
import SwanSpaces

/// The intentionally tiny notification passed to a delivery transport. The
/// stable event ID is its idempotency key. `payload` is always the canonical
/// lowercased UUID bytes generated by `SQLiteAccountDatabase`; it never holds
/// a reader envelope, record value, CID, credential, or endpoint secret.
public struct PermissionedSpaceOutboxNotification: Sendable, Equatable {
    public let id: UUID
    public let space: SpaceURI
    public let author: String
    public let revision: UInt64
    public let payload: Data
    public let attempts: Int

    init(event: PersistedOutboxEvent) {
        id = event.id
        space = event.space
        author = event.author
        revision = event.revision
        payload = event.payload
        attempts = event.attempts
    }
}

/// An injected, asynchronous boundary for best-effort notification delivery.
/// A successful remote delivery followed by a process crash is intentionally
/// retried after the durable lease expires (at-least-once semantics), so a
/// repeat must be harmless at the receiver. `notification.id` is the local
/// idempotency key; the HTTP transport does not reuse it as a service-JWT
/// `jti`, because receivers dedupe a repeated `notifyWrite` by revision.
public protocol PermissionedSpaceOutboxTransport: Sendable {
    func deliver(_ notification: PermissionedSpaceOutboxNotification) async throws
}

/// Bounded scheduling values for the durable outbox worker. Retrying is kept
/// in SQLite (`available_at`), not in actor memory, so a restart preserves the
/// current attempt count and deadline.
public struct PermissionedSpaceOutboxDeliveryConfiguration: Sendable, Equatable {
    public let leaseDuration: TimeInterval
    public let idlePollInterval: TimeInterval
    public let initialFailureBackoff: TimeInterval
    public let maximumFailureBackoff: TimeInterval

    public static let standard = PermissionedSpaceOutboxDeliveryConfiguration(
        validatedLeaseDuration: 30,
        idlePollInterval: 1,
        initialFailureBackoff: 1,
        maximumFailureBackoff: 60
    )

    public init(
        leaseDuration: TimeInterval = 30,
        idlePollInterval: TimeInterval = 1,
        initialFailureBackoff: TimeInterval = 1,
        maximumFailureBackoff: TimeInterval = 60
    ) throws {
        for (name, value) in [
            ("lease duration", leaseDuration),
            ("idle poll interval", idlePollInterval),
            ("initial failure backoff", initialFailureBackoff),
            ("maximum failure backoff", maximumFailureBackoff),
        ] {
            guard value.isFinite, value > 0, value <= 86_400 else {
                throw SwanError.malformed("\(name) must be between zero and one day")
            }
        }
        guard initialFailureBackoff <= maximumFailureBackoff else {
            throw SwanError.malformed("initial failure backoff exceeds maximum")
        }
        self.init(
            validatedLeaseDuration: leaseDuration,
            idlePollInterval: idlePollInterval,
            initialFailureBackoff: initialFailureBackoff,
            maximumFailureBackoff: maximumFailureBackoff
        )
    }

    private init(
        validatedLeaseDuration: TimeInterval,
        idlePollInterval: TimeInterval,
        initialFailureBackoff: TimeInterval,
        maximumFailureBackoff: TimeInterval
    ) {
        self.leaseDuration = validatedLeaseDuration
        self.idlePollInterval = idlePollInterval
        self.initialFailureBackoff = initialFailureBackoff
        self.maximumFailureBackoff = maximumFailureBackoff
    }

    func retryDelay(afterFailureAttempt attempts: Int) -> TimeInterval {
        // `attempts` is incremented only after a failed transport call. Clamp
        // the exponent as a second line of defense against overflow in a
        // corrupt-but-recoverable long-lived outbox row.
        let steps = max(0, min(attempts - 1, 30))
        var delay = initialFailureBackoff
        for _ in 0 ..< steps {
            delay = min(delay * 2, maximumFailureBackoff)
        }
        return delay
    }
}

public enum PermissionedSpaceOutboxDeliveryResult: Sendable, Equatable {
    case idle
    case delivered(eventID: UUID)
    case failed(eventID: UUID, attempts: Int)
    /// A former worker completed after its lease was reclaimed or after an
    /// operator removed the event. It must not mutate the newer lease.
    case leaseLost(eventID: UUID)
}

/// Coordinates best-effort notification delivery for one account database.
/// Every database operation commits before the transport is awaited, then a
/// completion/failure transaction compares the durable lease token. This
/// gives at-least-once delivery across worker crashes without keeping a SQLite
/// transaction or connection gate open during network I/O.
public actor PermissionedSpaceOutboxDeliveryWorker {
    private let database: SQLiteAccountDatabase
    private let transport: any PermissionedSpaceOutboxTransport
    private let configuration: PermissionedSpaceOutboxDeliveryConfiguration

    public init(
        database: SQLiteAccountDatabase,
        transport: any PermissionedSpaceOutboxTransport
    ) {
        self.init(
            database: database,
            transport: transport,
            configuration: .standard
        )
    }

    public init(
        database: SQLiteAccountDatabase,
        transport: any PermissionedSpaceOutboxTransport,
        configuration: PermissionedSpaceOutboxDeliveryConfiguration
    ) {
        self.database = database
        self.transport = transport
        self.configuration = configuration
    }

    /// Attempts at most one delivery. Supplying `now` makes lease expiry and
    /// retry scheduling deterministic in tests; production callers use the
    /// default wall clock. Transport errors are intentionally not persisted as
    /// strings because they can include endpoint details or credentials.
    public func deliverNext(
        now: Date = Date()
    ) async throws -> PermissionedSpaceOutboxDeliveryResult {
        guard let lease = try await database.leaseNextOutbox(
            now: now,
            leaseDuration: configuration.leaseDuration
        ) else {
            return .idle
        }
        // `attempts` is a persisted SQLite integer. A value at the host
        // integer maximum cannot advance safely, so leave its lease in place
        // and fail closed rather than trapping while handling a transport
        // error. It is diagnosable through the durable corruption path.
        guard lease.event.attempts < Int.max else {
            throw SQLiteRepositoryError.corruptDatabase("outbox attempts overflow")
        }
        let notification = PermissionedSpaceOutboxNotification(event: lease.event)

        do {
            // This is deliberately between the lease and completion database
            // calls. Never move it into either transaction.
            try await transport.deliver(notification)
            let completed = try await database.completeOutboxLease(
                eventID: lease.event.id,
                token: lease.token
            )
            return completed
                ? .delivered(eventID: lease.event.id)
                : .leaseLost(eventID: lease.event.id)
        } catch {
            let retryAt = now.addingTimeInterval(
                configuration.retryDelay(afterFailureAttempt: lease.event.attempts + 1)
            )
            guard let attempts = try await database.failOutboxLease(
                eventID: lease.event.id,
                token: lease.token,
                retryAt: retryAt
            ) else {
                return .leaseLost(eventID: lease.event.id)
            }
            return .failed(eventID: lease.event.id, attempts: attempts)
        }
    }

    /// Bounded-polling service-loop entry point. It exits promptly on task
    /// cancellation; the lease itself provides the crash-recovery boundary.
    public func runUntilCancelled() async {
        while !Task.isCancelled {
            do {
                let result = try await deliverNext()
                if case .idle = result {
                    try await Task.sleep(nanoseconds: nanoseconds(configuration.idlePollInterval))
                }
            } catch {
                // A transient SQLite issue should not terminate the service
                // loop. Do not retain or log arbitrary errors here: transport
                // and endpoint diagnostics belong to the caller's safe logger.
                try? await Task.sleep(nanoseconds: nanoseconds(configuration.idlePollInterval))
            }
        }
    }

    private func nanoseconds(_ interval: TimeInterval) -> UInt64 {
        UInt64((interval * 1_000_000_000).rounded(.up))
    }
}

public enum PermissionedSpaceSyncNotificationDisposition: Sendable, Equatable {
    case delivered
    case retryableFailure
    case rejected
}

public protocol PermissionedSpaceSyncNotificationTransport: Sendable {
    func deliver(
        _ notification: PersistedSpaceSyncNotification
    ) async -> PermissionedSpaceSyncNotificationDisposition
}

public enum PermissionedSpaceSyncNotificationDeliveryResult:
    Sendable, Equatable
{
    case idle
    case delivered(eventID: UUID)
    case failed(eventID: UUID, attempts: Int)
    case dropped(eventID: UUID)
    case leaseLost(eventID: UUID)
}

public actor PermissionedSpaceSyncNotificationDeliveryWorker {
    private static let reliableRetryDelays: [TimeInterval] = [
        60, 10 * 60, 60 * 60, 6 * 60 * 60, 12 * 60 * 60,
    ]

    private let database: SQLiteAccountDatabase
    private let transport: any PermissionedSpaceSyncNotificationTransport
    private let configuration: PermissionedSpaceOutboxDeliveryConfiguration

    public init(
        database: SQLiteAccountDatabase,
        transport: any PermissionedSpaceSyncNotificationTransport,
        configuration: PermissionedSpaceOutboxDeliveryConfiguration = .standard
    ) {
        self.database = database
        self.transport = transport
        self.configuration = configuration
    }

    public func deliverNext(
        now: Date = Date()
    ) async throws -> PermissionedSpaceSyncNotificationDeliveryResult {
        guard let lease = try await database.leaseNextSpaceSyncNotification(
            now: now,
            leaseDuration: configuration.leaseDuration
        ) else {
            return .idle
        }
        let event = lease.event
        guard try await database.spaceSyncNotificationIsOwed(event) else {
            return try await finish(lease, dropRegistration: false, delivered: false)
        }
        let disposition = await transport.deliver(event)
        switch disposition {
        case .delivered:
            return try await finish(lease, dropRegistration: false, delivered: true)
        case .rejected:
            return try await finish(lease, dropRegistration: true, delivered: false)
        case .retryableFailure where !event.isReliable:
            return try await finish(lease, dropRegistration: false, delivered: false)
        case .retryableFailure:
            guard let expiresAt = event.retryExpiresAt else {
                throw SQLiteRepositoryError.corruptDatabase(
                    "reliable space sync notification has no retry deadline"
                )
            }
            if now >= expiresAt {
                return try await finish(lease, dropRegistration: true, delivered: false)
            }
            let delay = Self.reliableRetryDelays[
                min(event.attempts, Self.reliableRetryDelays.count - 1)
            ]
            guard let attempts = try await database.failSpaceSyncNotificationLease(
                eventID: event.id,
                token: lease.token,
                retryAt: now.addingTimeInterval(delay)
            ) else {
                return .leaseLost(eventID: event.id)
            }
            return .failed(eventID: event.id, attempts: attempts)
        }
    }

    private func finish(
        _ lease: PersistedSpaceSyncNotificationLease,
        dropRegistration: Bool,
        delivered: Bool
    ) async throws -> PermissionedSpaceSyncNotificationDeliveryResult {
        let completed = try await database.completeSpaceSyncNotificationLease(
            eventID: lease.event.id,
            token: lease.token,
            dropRegistration: dropRegistration
        )
        guard completed else { return .leaseLost(eventID: lease.event.id) }
        return delivered
            ? .delivered(eventID: lease.event.id)
            : .dropped(eventID: lease.event.id)
    }

    public func runUntilCancelled() async {
        while !Task.isCancelled {
            do {
                if case .idle = try await deliverNext() {
                    try await Task.sleep(
                        nanoseconds: UInt64(
                            (configuration.idlePollInterval * 1_000_000_000)
                                .rounded(.up)
                        )
                    )
                }
            } catch {
                try? await Task.sleep(
                    nanoseconds: UInt64(
                        (configuration.idlePollInterval * 1_000_000_000)
                            .rounded(.up)
                    )
                )
            }
        }
    }
}
